/// <reference lib="webworker" />
/**
 * SEA-RAFT in a worker (vision/raft.ts), so neither the WASM fallback nor a long first WebGPU run blocks the page.
 * Messages: {type:'load', base, model} → {type:'ready', backend} | {type:'error', message};
 * {type:'flow', id, a, b} (planar RGB bytes) → {type:'flow', id, flow} | {type:'error', id, message}.
 */
import * as ort from 'onnxruntime-web/webgpu';

const S = 512;
let session: ort.InferenceSession | null = null;

const post = (m: unknown, t: Transferable[] = []) => (self as unknown as DedicatedWorkerGlobalScope).postMessage(m, t);

self.onmessage = async (e: MessageEvent) => {
  const m = e.data as
    { type: 'load'; base: string; model: ArrayBuffer; forceWasm?: boolean } | { type: 'flow'; id: number; a: Uint8Array; b: Uint8Array };
  try {
    if (m.type === 'load') {
      ort.env.wasm.wasmPaths = m.base;
      ort.env.wasm.numThreads = 1;
      let backend: 'webgpu' | 'wasm' = 'webgpu';
      const gpu = (navigator as Navigator & { gpu?: { requestAdapter(): Promise<unknown> } }).gpu;
      const adapter = gpu && !m.forceWasm ? await gpu.requestAdapter().catch(() => null) : null;
      const bytes = new Uint8Array(m.model);
      try {
        if (!adapter) throw new Error('no WebGPU adapter');
        session = await ort.InferenceSession.create(bytes, { executionProviders: ['webgpu'], graphOptimizationLevel: 'all' });
      } catch (err) {
        console.warn('SEA-RAFT: WebGPU unavailable, using WASM', err);
        backend = 'wasm';
        session = await ort.InferenceSession.create(bytes, { executionProviders: ['wasm'], graphOptimizationLevel: 'all' });
      }
      post({ type: 'ready', backend });
      return;
    }
    if (!session) throw new Error('model not loaded');
    const t = (c: Uint8Array) => new ort.Tensor('float32', Float32Array.from(c), [1, 3, S, S]);
    const out = await session.run({ image1: t(m.a), image2: t(m.b) });
    const f = out.flow!;
    const flow = Float32Array.from((await f.getData()) as Float32Array);
    f.dispose();
    post({ type: 'flow', id: m.id, flow }, [flow.buffer]);
  } catch (err) {
    post({ type: 'error', id: 'id' in m ? m.id : undefined, message: err instanceof Error ? err.message : String(err) });
  }
};
